/// <summary>
/// This a contract class for account status update job.
/// </summary>
[DataContract]
class METAccountStatusUpdateContract extends METSysOperationTaskDataContract implements SysOperationValidatable
{
    guid topPickingProcessId;
    str packedQuery;

}

Method.Source:
/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

/// <summary>
/// Gets/set packed query.
/// </summary>
/// <param name = "_packedQuery">Packed query.</param>
/// <returns>Packed query.</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METAccountStatusUpdate))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Validates the contract.
/// </summary>
/// <returns>True if valid; otherwise false.</returns>
public boolean validate()
{
    METCustParameters metCustParameters;
    boolean ret = true;

    metCustParameters = METCustParameters::Find();

    if (!metCustParameters.CustActiveAccountStatus)
    {
        ret = checkFailed(strFmt("@MET:CustAccountStatusNotSetWarning", fieldPName(METCustParameters, CustActiveAccountStatus)));
    }

    if (!metCustParameters.CustOnHoldAccountStatus)
    {
        ret = checkFailed(strFmt("@MET:CustAccountStatusNotSetWarning", fieldPName(METCustParameters, CustOnHoldAccountStatus)));

    }

    return ret;
}
